new='''/** Rows read per page while walking a project's content. */
const PAGE_SIZE = 100;

/**
 * Index writers. Each one applies the visibility rule itself: a project is
 * searchable while live, an issue while it and its project are live, a comment
 * while it, its issue and that issue's project are live. A subject that fails
 * the rule is removed from the index instead of upserted, so callers (write
 * listeners, the reindex job) can hand over any row and let the writer decide.
 * They resolve to whether the subject is now in the index.
 */
export async function indexIssue(
  orgId: OrgId,
  issue: Issue,
): Promise<boolean> {
  if (!(await isIssueSearchable(orgId, issue))) {
    await removeFromIndex(orgId, "issue", issue.id);
    return false;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\\n"),
    issue.projectId,
  );
  return true;
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<boolean> {
  const issue =
    comment.archivedAt === null
      ? await issueRepo.findIssueById(orgId, comment.issueId)
      : null;

  if (!issue || !(await isIssueSearchable(orgId, issue))) {
    await removeFromIndex(orgId, "comment", comment.id);
    return false;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
  return true;
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<boolean> {
  if (project.archivedAt !== null) {
    await removeFromIndex(orgId, "project", project.id);
    return false;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\\n"),
    project.id,
  );
  return true;
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

async function isIssueSearchable(orgId: OrgId, issue: Issue): Promise<boolean> {
  if (issue.archivedAt !== null) return false;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project !== null && project.archivedAt === null;
}

/**
 * Brings a project's live content back into the index after a restore. Issues
 * that are still archived are skipped, and so are their comments: restoring a
 * project never restores what was archived alongside or before it.
 */
async function reindexProjectContent(
  orgId: OrgId,
  projectId: Project["id"],
): Promise<void> {
  let issueCursor: string | null = null;
  do {
    const issues = await issueRepo.listIssues({
      orgId,
      projectId,
      limit: PAGE_SIZE,
      cursor: issueCursor,
    });

    for (const issue of issues.items) {
      if (!(await indexIssue(orgId, issue))) continue;

      let commentCursor: string | null = null;
      do {
        const thread = await commentRepo.listComments({
          orgId,
          issueId: issue.id,
          includeArchived: false,
          limit: PAGE_SIZE,
          cursor: commentCursor,
        });
        for (const comment of thread.items) await indexComment(orgId, comment);
        commentCursor = thread.nextCursor;
      } while (commentCursor !== null);
    }

    issueCursor = issues.nextCursor;
  } while (issueCursor !== null);
}

async function reindexIssue(orgId: OrgId, issueId: Issue["id"]): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue) await indexIssue(orgId, issue);
  else await removeFromIndex(orgId, "issue", issueId);
}

async function reindexComment(
  orgId: OrgId,
  commentId: Comment["id"],
): Promise<void> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (comment) await indexComment(orgId, comment);
  else await removeFromIndex(orgId, "comment", commentId);
}

async function reindexProject(
  orgId: OrgId,
  projectId: Project["id"],
): Promise<boolean> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (!project) {
    await removeFromIndex(orgId, "project", projectId);
    return false;
  }
  return indexProject(orgId, project);
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
