s=open(p).read()
start=s.index('/**\n * Walks one tenant')
new='''/**
 * Walks one tenant's projects, issues and comments — every page of each — and
 * re-upserts every document the index writers accept. Scoped to a single org on
 * purpose: a full-fleet reindex is a sequence of these, so one slow tenant
 * cannot stall the rest.
 *
 * Archived rows are read too, but the writers decide whether a subject is
 * searchable (see `indexProject` / `indexIssue` / `indexComment`) and report
 * it. Once the whole tenant has been walked, every document of that tenant the
 * writers did not accept — archived subjects, subjects under an archived
 * parent, orphans of rows that no longer exist — is pruned, so the rebuild
 * leaves exactly the documents the visibility rule allows. Other tenants'
 * documents are never read or written.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const keep = new Set<string>();
    let complete = true;

    let projectCursor: string | null = null;
    do {
      const projects: Page<Project> = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
        includeArchived: true,
      });

      for (const project of projects.items) {
        try {
          if (await indexProject(orgId, project)) {
            keep.add(searchDocumentKey("project", project.id));
          }
          result.processed += 1;
        } catch (error) {
          // Unknown outcome: leave whatever the index already holds.
          keep.add(searchDocumentKey("project", project.id));
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
