/**
 * Search visibility: a project is findable while live, an issue while it and
 * its project are live, a comment while it, its issue and its project are
 * live — through archive, restore, later writes and a full index rebuild.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;
let counter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
});

async function newProject(tenant: Tenant, name: string) {
  counter += 1;
  return projectService.createProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    name,
    slug: `${name.toLowerCase()}-${counter}`,
    key: `K${counter}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

async function addIssue(tenant: Tenant, projectId: Tenant["project"]["id"], title: string) {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title }),
  );
}

async function addComment(tenant: Tenant, issueId: string, body: string) {
  return commentService.createComment(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issueId as never,
    body,
    parentId: null,
    mentionedUserIds: [],
  });
}

async function found(tenant: Tenant, q: string) {
  const page = await searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds: ["issue", "comment", "project"],
    limit: 100,
    cursor: null,
  });
  return { total: page.total, ids: page.items.map((item) => item.id).sort() };
}

describe("search visibility", () => {
  it("hides the comments of an archived issue", async () => {
    const tenant = await createTenant("vis-issue");
    const issue = await addIssue(tenant, tenant.project.id, "VisIssueAlpha");
    const comment = await addComment(tenant, issue.id, "VisIssueAlpha remark");
    expect((await found(tenant, "VisIssueAlpha")).total).toBe(2);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    expect(await found(tenant, "VisIssueAlpha")).toEqual({ total: 0, ids: [] });
    expect(comment.id).toBeTruthy();
  });

  it("hides an archived project's content, kept issues included, and their later writes", async () => {
    const tenant = await createTenant("vis-project");
    const project = await newProject(tenant, "VisProjectBeta");
    const issue = await addIssue(tenant, project.id, "VisProjectBeta issue");
    await addComment(tenant, issue.id, "VisProjectBeta comment");
    expect((await found(tenant, "VisProjectBeta")).total).toBe(3);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });
    expect((await found(tenant, "VisProjectBeta")).total).toBe(0);

    await addComment(tenant, issue.id, "VisProjectBeta later comment");
    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "VisProjectBeta edited",
    });
    expect((await found(tenant, "VisProjectBeta")).total).toBe(0);
  });

  it("brings a restored project and its live content back, but not archived issues", async () => {
    const tenant = await createTenant("vis-restore");
    const project = await newProject(tenant, "VisRestoreGamma");
    const kept = await addIssue(tenant, project.id, "VisRestoreGamma kept");
    const keptComment = await addComment(tenant, kept.id, "VisRestoreGamma kept note");
    const early = await addIssue(tenant, project.id, "VisRestoreGamma early");
    await addComment(tenant, early.id, "VisRestoreGamma early note");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, early.id);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, project.id);

    const after = await found(tenant, "VisRestoreGamma");
    expect(after.ids).toEqual([project.id, kept.id, keptComment.id].sort());
    expect(after.total).toBe(3);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: true,
